// === Constants ===
// Prices per 1M tokens in USD (OpenAI list price, checked on PRICE_STAND,
// source: https://developers.openai.com/api/docs/pricing)
const PRICES_USD = {
  'gpt-4o-mini': { in: 0.15, out: 0.60 },
  'gpt-4o':      { in: 2.50, out: 10.00 },
};
const PRICE_STAND = '2026-10-07';
// ECB reference rate 1 EUR = x USD (as of 2026-09-15)
const USD_PER_EUR = 1.1539;
// Fallback if the model cannot be read from the execution
const DEFAULT_MODEL = 'gpt-4o-mini';
// Input node names in the chat workflow (web chat and Telegram)
const CHAT_INPUT_NODES = ['When chat message received', 'Telegram Input'];
const CHAT_MODEL = 'OpenAI Chat Model';
// Sessions with these prefixes are test runs
const TEST_SESSION_PREFIXES = ['test-', 'r1-', 'r2-', 'r3-'];

const ex = $input.first().json;

// === Execution must be finished, otherwise tokens are missing ===
if (!ex.finished && ex.status !== 'error') {
  throw new Error('Execution ' + ex.id + ' is not finished yet (status: ' + ex.status + ')');
}
const runData = ex.data?.resultData?.runData ?? {};

// === Sum tokens (all model calls of this execution) ===
// tokenUsage = real API numbers, tokenUsageEstimate = estimate by n8n
let prompt = 0, completion = 0;
for (const run of runData[CHAT_MODEL] ?? []) {
  for (const out of run.data?.ai_languageModel?.[0] ?? []) {
    const u = out.json?.tokenUsage ?? out.json?.tokenUsageEstimate ?? {};
    prompt += u.promptTokens ?? 0;
    completion += u.completionTokens ?? 0;
  }
}
if (prompt + completion === 0) return []; // no model call, nothing to log

// === Question: only length and sessionId, no plain text ===
const inputNode = CHAT_INPUT_NODES.find(n => runData[n]);
const trig = runData[inputNode]?.[0]?.data?.main?.[0]?.[0]?.json ?? {};
const question = trig.chatInput ?? '';
const sessionId = String(trig.sessionId ?? '');

// === Model from the workflow version of the execution ===
const modelNode = (ex.workflowData?.nodes ?? []).find(n => n.name === CHAT_MODEL);
const m = modelNode?.parameters?.model;
const model = (typeof m === 'object' ? m?.value : m) || DEFAULT_MODEL;

// === Cost ===
const p = PRICES_USD[model];
const costUsd = p ? (prompt * p.in + completion * p.out) / 1e6 : null;

return [{ json: {
  created_at: ex.startedAt,
  workflow: 'compliance-bot-chat',
  execution_id: String(ex.id),
  model,
  prompt_tokens: prompt,
  completion_tokens: completion,
  total_tokens: prompt + completion,
  cost_eur: costUsd === null ? null : Number((costUsd / USD_PER_EUR).toFixed(6)),
  price_stand: PRICE_STAND,
  question_chars: question.length,
  is_test: ex.mode !== 'webhook' || TEST_SESSION_PREFIXES.some(t => sessionId.startsWith(t)),
}}];

// === Constants ===
// Daily limit in EUR (real questions only, without tests). A warning follows above it.
const DAY_LIMIT_EUR = 1.00;

// Number format with fixed decimals: 0.031
const fmt = (n, d) => Number(n).toFixed(d);

// === Data ===
const current = $('Calculate Tokens and Cost').first().json;
const chatId = $('Execute Workflow Trigger').first().json.chatId;
// Rows of today (is_test = false); the row just written is included
const todayRows = $input.all().map(i => i.json).filter(r => r.execution_id);
const todaySum = todayRows.reduce((s, r) => s + Number(r.cost_eur ?? 0), 0);

// === Text ===
let text = 'This question: ' + fmt(current.cost_eur ?? 0, 3) + ' EUR (' + current.model + ', '
  + current.total_tokens + ' tokens).\n'
  + 'Today in total: ' + fmt(todaySum, 3) + ' EUR of ' + fmt(DAY_LIMIT_EUR, 2) + ' EUR.';
if (current.is_test) text += '\n(Test run, not counted in the daily total)';
if (todaySum > DAY_LIMIT_EUR) text += '\nWARNING: daily limit exceeded!';

return [{ json: { chatId, text } }];
